// Format Validator Code Node
// Memvalidasi ekstensi file: hanya pdf, docx, txt yang diterima
// Requirements: 1.2

const items = $input.all();
const results = [];

for (const item of items) {
  // Normalisasi data dari berbagai sumber (Gmail, Webhook, Google Drive)
  const filename = item.json.filename
    || item.json.name
    || item.json.subject
    || '';

  const source = item.json.source
    || (item.json.headers ? 'webhook' : '')
    || (item.json.mimeType ? 'google_drive' : '')
    || 'unknown';

  const ext = filename.split('.').pop()?.toLowerCase() || '';
  const validExtensions = ['pdf', 'docx', 'txt'];

  if (!validExtensions.includes(ext)) {
    results.push({
      json: {
        ...item.json,
        filename,
        source,
        valid: false,
        errorCode: 'INVALID_FORMAT',
        errorMessage: `File extension '.${ext}' tidak diizinkan. Hanya pdf, docx, txt yang diterima.`
      }
    });
  } else {
    results.push({
      json: {
        ...item.json,
        filename,
        source,
        extension: ext,
        valid: true
      }
    });
  }
}

return results;

// Size Validator Code Node
// Memvalidasi ukuran file: maksimum 10MB (10485760 bytes)
// Requirements: 1.5

const MAX_SIZE_BYTES = 10 * 1024 * 1024; // 10MB
const items = $input.all();
const results = [];

for (const item of items) {
  // Coba dapatkan ukuran file dari berbagai field yang mungkin ada
  const sizeBytes = item.json.sizeBytes
    || item.json.size
    || item.json.fileSize
    || item.json.attachmentSize
    || (item.binary?.data?.fileSize)
    || 0;

  const numericSize = typeof sizeBytes === 'string'
    ? parseInt(sizeBytes, 10)
    : Number(sizeBytes);

  if (!Number.isFinite(numericSize) || numericSize > MAX_SIZE_BYTES) {
    results.push({
      json: {
        ...item.json,
        valid: false,
        errorCode: 'FILE_TOO_LARGE',
        errorMessage: `Ukuran file ${numericSize} bytes melebihi batas maksimum 10MB (${MAX_SIZE_BYTES} bytes).`,
        sizeBytes: numericSize
      }
    });
  } else {
    results.push({
      json: {
        ...item.json,
        valid: true,
        sizeBytes: numericSize
      }
    });
  }
}

return results;

// Rate Limiter Code Node
// Mengecek rate limit menggunakan Redis counter dengan TTL 60 detik
// Requirements: 1.7, 11.5
// Catatan: Di n8n, akses Redis dilakukan via Redis Node terpisah.
// Code Node ini menyiapkan data untuk Redis Node dan mengecek hasil.

const items = $input.all();
const results = [];

for (const item of items) {
  // Tandai item untuk pengecekan rate limit
  // Redis Node berikutnya akan melakukan INCR dan TTL check
  results.push({
    json: {
      ...item.json,
      rateLimitKey: 'rate_limit:cv_intake',
      rateLimitTtl: 60,
      maxRequests: 50,
      checkRateLimit: true
    }
  });
}

return results;

// Rate Limit Check Code Node
// Memeriksa apakah counter melebihi batas dan menyiapkan response
// Requirements: 1.7

const items = $input.all();
const results = [];

for (const item of items) {
  const currentCount = item.json.value || 0;
  const maxRequests = item.json.maxRequests || 50;

  if (currentCount > maxRequests) {
    // Rate limit terlampaui
    results.push({
      json: {
        ...item.json,
        rateLimitExceeded: true,
        retryAfter: 60, // TTL default 60 detik
        errorCode: 'QUEUE_FULL',
        errorMessage: `Rate limit terlampaui. Maksimum ${maxRequests} request per 60 detik. Coba lagi dalam 60 detik.`
      }
    });
  } else {
    results.push({
      json: {
        ...item.json,
        rateLimitExceeded: false
      }
    });
  }
}

return results;

// File Encryptor Code Node
// Mengenkripsi file CV menggunakan AES-256-CBC sebelum disimpan ke storage
// Requirements: 10.1

const crypto = require('crypto');
const { v4: uuidv4 } = require('uuid');

const ALGORITHM = 'aes-256-cbc';
const IV_LENGTH = 16;

function getEncryptionKey() {
  const rawKey = process.env.ENCRYPTION_KEY || process.env.FILE_ENCRYPTION_KEY;
  if (!rawKey) {
    throw new Error('ENCRYPTION_KEY environment variable tidak dikonfigurasi');
  }
  if (/^[0-9a-fA-F]{64}$/.test(rawKey)) {
    return Buffer.from(rawKey, 'hex');
  }
  const keyBuffer = Buffer.from(rawKey, 'utf8');
  if (keyBuffer.length !== 32) {
    throw new Error('ENCRYPTION_KEY harus 32 bytes (256-bit)');
  }
  return keyBuffer;
}

const items = $input.all();
const results = [];

for (const item of items) {
  try {
    // Dapatkan konten file dari binary data atau base64
    let fileBuffer;
    if (item.binary && item.binary.data) {
      fileBuffer = Buffer.from(item.binary.data.data, 'base64');
    } else if (item.json.fileContent) {
      fileBuffer = Buffer.from(item.json.fileContent, 'base64');
    } else {
      // Fallback: gunakan placeholder untuk testing
      fileBuffer = Buffer.from(JSON.stringify(item.json));
    }

    const key = getEncryptionKey();
    const iv = crypto.randomBytes(IV_LENGTH);
    const cipher = crypto.createCipheriv(ALGORITHM, key, iv);
    const encrypted = Buffer.concat([cipher.update(fileBuffer), cipher.final()]);
    const encryptedString = `${iv.toString('hex')}:${encrypted.toString('hex')}`;

    // Generate S3 key untuk file terenkripsi
    const jobId = item.json.jobId || uuidv4();
    const timestamp = new Date().toISOString().split('T')[0]; // YYYY-MM-DD
    const fileKey = `cv/encrypted/${timestamp}/${jobId}.enc`;

    results.push({
      json: {
        ...item.json,
        jobId,
        fileKey,
        encryptedContent: encryptedString,
        enqueuedAt: new Date().toISOString(),
        encrypted: true
      }
    });
  } catch (err) {
    results.push({
      json: {
        ...item.json,
        encryptionError: err.message,
        valid: false,
        errorCode: 'ENCRYPTION_FAILED'
      }
    });
  }
}

return results;
